import React, { useEffect } from "react";

export default function MobileDrawer({ open, onClose, children }) {
  useEffect(() => {
    document.body.style.overflow = open ? "hidden" : "";
    return () => { document.body.style.overflow = ""; };
  }, [open]);

  return (
    <>
      {/* Backdrop */}
      <div
        className={`fixed inset-0 bg-black/60 backdrop-blur-sm z-40 transition-opacity duration-300
          lg:hidden ${open ? "opacity-100 pointer-events-auto" : "opacity-0 pointer-events-none"}`}
        onClick={onClose}
      />
      {/* Drawer */}
      <div
        className={`fixed top-0 left-0 bottom-0 z-50 transition-transform duration-300 ease-out
          lg:hidden ${open ? "translate-x-0" : "-translate-x-full"}`}
      >
        {children}
      </div>
    </>
  );
}
